def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def count_ways(n):
    if n <= 1:
        return 1
    return count_ways(n - 1) + count_ways(n - 2)

def count_most_frequent(s):
    best, bn, seen = None, 0, {}
    for c in s:
        seen[c] = seen.get(c, 0) + 1
        if seen[c] > bn:
            best, bn = c, seen[c]
    return best

def remove_duplicates_sorted(lst):
    out = []
    for x in lst:
        if not out or out[-1] != x:
            out.append(x)
    return out

def count_chars(s):
    d = {}
    for c in s:
        d[c] = d.get(c, 0) + 1
    return d

